    "factor_updates": [
      {
        "factor": "ULCC-sector distress signals and peer bankruptcy risk",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "ULCC-focused models indicate elevated near-term bankruptcy risk for the sector, with distress indicators (e.g., low Z-scores and 45–46% probabilities in related forecasts) contributing upward pressure on Frontier's risk."
      },
      {
        "factor": "Frontier liquidity cushion via revolving credit facility",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Liquidity facilities (undrawn revolver around $205 million; substantial total liquidity) reduce near-term failure risk and support ongoing operations."
      },
      {
        "factor": "Frontier corporate leverage context",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "High debt levels and refinancing risks in the ULCC space contribute to upward pressure on default risk."
      },
      {
        "factor": "Macro distress environment and rising 2025 bankruptcy filings",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Industry-wide distress in 2025 raises the baseline risk for leveraged carriers, though not deterministically translating to Frontier bankruptcy with current mitigants."
      },
      {
        "factor": "Frontier consolidation / merger activity with Spirit",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Strategic consolidation could improve scale and liquidity, reducing bankruptcy risk in the near term."
      },
      {
        "factor": "ULCC base-rate guidance and absence of Frontier-specific bankruptcy signals",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "No clear Frontier bankruptcy signals in the provided sources, supporting a downshift from the high sector-risk baseline."
      }
    ],
    "synthesis_rationale": "A Bayesian synthesis started with a high-sector-risk anchor and applied both upward and downward updates from Frontier-specific liquidity, leverage, and strategic actions, calibrating to a conservative posterior of 12% to reflect mixed signals and limited Frontier-specific distress indicators. The range accounts for uncertainty in macro conditions and potential tail events, with higher confidence in mitigants like liquidity and merger activity.",
  "notes": "Calibration acknowledges strongest upward pressure from sector distress while acknowledging Frontier-specific mitigants that reduce near-term bankruptcy risk."
  }
}

